sp_widget.client_script:
/*
  CLM Customer 360 (MD1) — Client Script  v2.3
  - Business filter (single select): c.business. Customer search is disabled until a business is chosen
  - c.businessOptions cached from the first server payload (data.businessOptions); fallback kept here
  - Search placeholder / hint come from the selected business (Trade & Non-Trade: name, PAN, code;
    Key Customer: name, group code, grandparent code, PAN)
  - Every server call (suggest / load / fetch_live_sap) sends business
  - Changing business clears the current customer, search box, suggestions and charts
  - Opening a customer from Portfolio Overview switches to the business in the payload
    (payload.business or $rootScope.clmPendingCustomerBusiness, default Trade)
  - LAYOUTS registry: Trade view logic (site selection, charts, live SAP fetch) moved into
    tradeOnLoaded(); Non-Trade / Key Customer plug in their own handlers later
  - Stale responses ignored when the user searches or switches business quickly
  - $rootScope listener is now removed on $destroy
  v2.1 / v2.0 — chart styling, live SAP merge, 6-month detail (unchanged)
*/
function CLMCustomer360MDController($scope, $timeout, $rootScope, $document) {
    var c = this;

    c.searchTerm = '';
    c.loading = true;
    c.sapLoading = false;
    c.charts = {};

    c.suggestions    = [];
    c.suggestLoading = false;
    var _suggestTimer = null;
    var loadReqId = 0;
    var suggestReqId = 0;

    c.selectedSite = '';
    c.siteSearch = '';
    c.siteDropdownOpen = false;
    c.selectedMonth = '';
    c.tableData = [];

    // ===================== BUSINESS FILTER =====================
    var FALLBACK_BUSINESS_OPTIONS = [
        { value: 'trade',    label: 'Trade',        layout: 'trade',    enabled: true,
          searchPlaceholder: 'Customer name, PAN or customer code', searchHint: 'customer name, PAN or customer code' },
        { value: 'nonTrade', label: 'Non-Trade',    layout: 'nonTrade', enabled: true,
  searchPlaceholder: 'Customer name, PAN or customer code', searchHint: 'customer name, PAN or customer code' },
        { value: 'key',      label: 'Key Customer', layout: 'key',      enabled: true,
          searchPlaceholder: 'Customer name, group code, grandparent code or PAN', searchHint: 'customer name, group code, grandparent code or PAN' }
    ];
    c.businessOptions = (c.data && c.data.businessOptions && c.data.businessOptions.length) ? c.data.businessOptions : FALLBACK_BUSINESS_OPTIONS;
    var DEFAULT_BUSINESS = (c.data && c.data.defaultBusiness) || 'trade';

c.business = DEFAULT_BUSINESS;          // this widget is the Trade view, so Trade is always preselected
var activeBusiness = DEFAULT_BUSINESS;  // last accepted value

    function getBusinessOption(v) {
        for (var i = 0; i < c.businessOptions.length; i++) { if (c.businessOptions[i].value === v) return c.businessOptions[i]; }
        return null;
    }
    c.getBusinessOptionText = function(b) { return b.label + (b.enabled ? '' : ' (Coming soon)'); };
    c.getBusinessLabel = function() { var b = getBusinessOption(c.business); return b ? b.label : ''; };
    c.getLayout = function() { var b = getBusinessOption(c.business); return b ? b.layout : ''; };
    c.isBusinessSupported = function() { var b = getBusinessOption(c.business); return !!(b && b.enabled && LAYOUTS[b.layout]); };
    c.isLayout = function(name) { return c.isBusinessSupported() && c.getLayout() === name; };
    c.isSearchEnabled = function() { return c.isBusinessSupported(); };
    c.getSearchPlaceholder = function() {
        var b = getBusinessOption(c.business);
        return b ? (b.searchPlaceholder || 'Search customer') : 'Select a business first';
    };
    c.getSearchHint = function() { var b = getBusinessOption(c.business); return b ? (b.searchHint || '') : ''; };

    function resetCustomerView() {
        ++loadReqId; ++suggestReqId;
        if (_suggestTimer) { $timeout.cancel(_suggestTimer); _suggestTimer = null; }
        destroyAllCharts();
        c.searchTerm = '';
        c.suggestions = []; c.suggestLoading = false;
        c.selectedSite = ''; c.siteSearch = ''; c.siteDropdownOpen = false;
        c.selectedMonth = ''; c.tableData = [];
        c.sapLoading = false; c.loading = false;
        c.data = { initialLoad: true };
    }

    // Switch business programmatically (used by the Portfolio Overview hand-off)
function applyBusiness(value) {
    var opt = getBusinessOption(value);
    if (!opt || !opt.enabled || !LAYOUTS[opt.layout]) return false;
    if (value !== activeBusiness) { resetCustomerView(); }
    c.business = value;
    activeBusiness = value;
    return true;
}

c.onBusinessChange = function() {
    var opt = getBusinessOption(c.business);
    if (!opt || !opt.enabled) { c.business = activeBusiness; return; }
    if (c.business === activeBusiness) return;

    // Non-Trade / Key are served by their own widgets: ask the dashboard to open that Customer 360
    if (!LAYOUTS[opt.layout]) {
        $rootScope.$broadcast('clm.business.changed', { business: opt.value, cg1: opt.cg1, from: 'trade', keepTab: true });
        $timeout(function() { c.business = activeBusiness; });
        return;
    }

    activeBusiness = c.business;
    resetCustomerView();
};

    var CHART_JS_URL = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
    var CHART_FONT = '"Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif';

    function ensureChartJs(cb) {
        if (typeof Chart !== 'undefined') { cb(); return; }
        if (!window.__clmChartJsPromise) {
            window.__clmChartJsPromise = new Promise(function(resolve, reject) {
                var existing = document.querySelector('script[data-clm-chartjs]');
                if (existing) {
                    existing.addEventListener('load', resolve);
                    existing.addEventListener('error', reject);
                    return;
                }
                var script = document.createElement('script');
                script.src = CHART_JS_URL;
                script.setAttribute('data-clm-chartjs', 'true');
                script.onload = resolve;
                script.onerror = reject;
                document.head.appendChild(script);
            });
        }
        window.__clmChartJsPromise.then(function() { $timeout(cb); }).catch(function(err) { console.error('CLM Widget: failed to load Chart.js', err); });
    }

    ensureChartJs(function() {});

    function handleClickOutside(event) {
        var target = event.target;
        if (!target.closest('.clm-custom-dropdown')) {
            $timeout(function() { c.siteDropdownOpen = false; });
        }
    }
    $document.on('click', handleClickOutside);
    $scope.$on('$destroy', function() { $document.off('click', handleClickOutside); });

    // =================================================================
    // FORMATTERS
    // =================================================================
    c.fmtDynamic = function(val) {
        if (val === null || val === undefined || val === '') return '—';

        var numericVal = parseFloat(String(val).replace(/,/g, ''));
        if (isNaN(numericVal)) return '—';
        if (numericVal === 0) return '₹0';

        var absVal = Math.abs(numericVal);
        var sign = numericVal < 0 ? '-' : '';

        if (absVal >= 10000000) {
            return sign + '₹' + (absVal / 10000000).toFixed(2) + 'Cr';
        } else if (absVal >= 100000) {
            return sign + '₹' + (absVal / 100000).toFixed(2) + 'L';
        } else if (absVal >= 1000) {
            return sign + '₹' + (absVal / 1000).toFixed(1) + 'K';
        } else {
            return sign + '₹' + (absVal % 1 === 0 ? absVal : absVal.toFixed(2));
        }
    };

    c.fmtLakh = c.fmtDynamic;
    c.fmtK = c.fmtDynamic;

    c.fmtDash = function(val) {
        var p = parseFloat(val);
        return (!val || isNaN(p) || p === 0) ? '—' : c.fmtDynamic(p);
    };

    c.fmtRatio = function(value) {
        var p = parseFloat(value);
        return (value === undefined || value === null || isNaN(p)) ? '—' : p.toFixed(2);
    };

    c.capPct = function(pct) {
        var p = parseFloat(pct);
        if (isNaN(p)) return 0;
        return Math.max(0, Math.min(100, p));
    };

    c.fmtPercent = function(val) {
        var p = parseFloat(val);
        if (isNaN(p)) return '—';
        var rounded = Math.round(p * 10) / 10;
        var sign = rounded > 0 ? '+' : '';
        return sign + rounded.toFixed(1) + '%';
    };

    c.riskValueClass = function(val) {
        if (val === null || val === undefined || isNaN(val)) return 'clm-risk-neutral';
        if (val < 0) return 'clm-risk-negative';
        if (val > 0) return 'clm-risk-positive';
        return 'clm-risk-neutral';
    };

    var parseSafeNumber = function(val) {
        if (val === null || val === undefined) return 0;
        if (typeof val === 'number') return isNaN(val) ? 0 : val;
        var str = String(val).replace(/[₹\s,]/g, '').trim();
        var multiplier = 1;
        if (str.toUpperCase().endsWith('L')) { multiplier = 100000; str = str.slice(0, -1); }
        else if (str.toUpperCase().endsWith('K')) { multiplier = 1000; str = str.slice(0, -1); }
        var num = parseFloat(str);
        return isNaN(num) ? 0 : num * multiplier;
    };

    // =================================================================
    // SEARCH (only after a business is selected)
    // =================================================================
    c.onTyping = function($event) {
        if (!c.isSearchEnabled()) { c.suggestions = []; return; }
        if ($event.keyCode === 13) { c.suggestions = []; c.doSearch(); return; }
        if ($event.keyCode === 27) { c.suggestions = []; return; }

        var term = (c.searchTerm || '').trim();
        if (term.length < 2) {
            c.suggestions = []; c.suggestLoading = false;
            if (_suggestTimer) { $timeout.cancel(_suggestTimer); }
            return;
        }

        if (_suggestTimer) { $timeout.cancel(_suggestTimer); }
        _suggestTimer = $timeout(function() {
            var myId = ++suggestReqId;
            c.suggestLoading = true;
            c.server.get({ action: 'suggest', term: term, business: c.business }).then(function(r) {
                if (myId !== suggestReqId) return;
                c.suggestions    = (r.data && r.data.suggestions) || [];
                c.suggestLoading = false;
            }, function() {
                if (myId !== suggestReqId) return;
                c.suggestions    = []; c.suggestLoading = false;
            });
        }, 250);
    };

    c.selectSuggestion = function(s) {
        if (!c.isSearchEnabled()) return;
        c.searchTerm  = s.pan || s.code;
        c.suggestions = [];
        c.selectedMonth = '';
        if (s.sysId) { c.load({ sysId: s.sysId, code: s.code, pan: s.pan }); }
        else { c.load(s.pan); }
    };

    c.doSearch = function() {
        if (!c.isSearchEnabled()) return;
        if (c.searchTerm && c.searchTerm.trim() !== '') {
            c.selectedMonth = '';
            c.load(c.searchTerm.trim());
        }
    };

    // =================================================================
    // LOAD (generic) -> hands the payload to the active layout
    // =================================================================
    c.load = function(param) {
        var myId = ++loadReqId;
        c.loading = true;
        c.sapLoading = false;
        c.suggestions = [];

        var payload = {};
        if (param && typeof param === 'object') {
            if (param.sysId) payload.sysId = param.sysId;
            c.searchTerm = param.pan || param.code || c.searchTerm;
        } else {
            payload = { search: param || '' };
            c.searchTerm = param || c.searchTerm;
        }
        if (c.business) payload.business = c.business;   // empty only for the initial / deep-link load

        c.server.get(payload).then(function(r) {
            if (myId !== loadReqId) return;
            c.data = r.data || {};

            // Server confirms the business it used (deep links default to Trade)
            if (c.data.business && c.data.business !== c.business && getBusinessOption(c.data.business)) {
                c.business = c.data.business;
                activeBusiness = c.data.business;
            }

            if (c.data.error || !c.data.panIdentity) { c.loading = false; return; }

            var layout = LAYOUTS[c.getLayout()];
            if (!layout || !layout.onLoaded) { c.loading = false; return; }
            layout.onLoaded(myId);
        }, function() {
            if (myId !== loadReqId) return;
            c.loading = false;
        });
    };

    // =================================================================
    // TRADE LAYOUT
    // =================================================================
    function tradeOnLoaded(myId) {
        if (c.data.panIdentity && c.data.panIdentity.pan) {
            c.searchTerm = c.data.panIdentity.pan;
        }

        c.selectedMonth = c.data.selectedMonthVal;

        if (c.data.siteList && c.data.siteList.length > 0) {
            var initialSite = c.data.siteList[0];
            c.selectedSite = initialSite.sysId;
            c.siteSearch = initialSite.code + ' · ' + initialSite.segment;
        }

        c.loading = false;
        c.updateTable();
        c.onMonthChange();

        $timeout(function() {
            c.drawSalesChart();
            c.drawAgingChart();
        }, 300);

        /*if (c.data.siteList && c.data.siteList.length > 0) {
            c.sapLoading = true;
            var sitesForSap = c.data.siteList.map(function(s) { return { code: s.code, sysId: s.sysId, salesOrg: s.salesOrg }; });

            c.server.get({ action: 'fetch_live_sap', sites: sitesForSap, business: c.business }).then(function(sapRes) {
                if (myId !== loadReqId) return;
                c.mergeSapData(sapRes.data && sapRes.data.liveResults);
                c.sapLoading = false;
            }, function() {
                if (myId !== loadReqId) return;
                c.sapLoading = false;
            });
        }*/
			        c.sapLoading = false;
    }

    function destroyAllCharts() {
        if (typeof Chart === 'undefined') { c.charts = {}; return; }
        ['c360SalesChartMD', 'c360AgingChartMD'].forEach(function(id) {
            var canvas = document.getElementById(id);
            var existing = canvas ? Chart.getChart(canvas) : null;
            if (existing) { try { existing.destroy(); } catch (e) {} }
        });
        c.charts = {};
    }

    // Layout registry — add nonTrade / key when their views are built:
    //   nonTrade: { onLoaded: nonTradeOnLoaded },
    //   key:      { onLoaded: keyOnLoaded }
    var LAYOUTS = {
        trade: { onLoaded: tradeOnLoaded }
    };

    /*c.mergeSapData = function(liveResults) {
        if (!liveResults || !c.data || !c.data.siteList) return;
        var aggReqOutst = 0;
        var aggLimit = 0;
        var anyApiSuccess = false;

        c.data.siteList.forEach(function(site) {
            var sapData = liveResults[site.sysId];
            if (sapData) {
                if (sapData.success) anyApiSuccess = true;
                site.liveOutst = sapData.liveOutst || 0;

                if (sapData.limit > 0) site.limit = sapData.limit;

                if (sapData.activeSd !== undefined && sapData.activeSd !== null) {
                    site.activeSd = sapData.activeSd;
                }
            }
            aggReqOutst += site.liveOutst;
            aggLimit += (parseFloat(site.limit) || 0);
        });

        c.data.liveApiOk = anyApiSuccess;
        c.data.liveAggOutst = aggReqOutst;

        c.data.indicators.limit = aggLimit;
        c.data.indicators.aggregateOutstanding = aggReqOutst;
        c.data.indicators.available = aggLimit - aggReqOutst;
        c.data.indicators.utilisation = aggLimit > 0 ? Math.round((aggReqOutst / aggLimit) * 100) : 0;

        c.onMonthChange();
    };*/

    c.onMonthChange = function() {
        if (!c.data || !c.data.siteList || !c.data.filterMonths) return;

        var isLatestMonth = (c.selectedMonth === c.data.filterMonths[0].value);

        c.data.table1Data = [];
        var activeSdTotal = 0, aggLimit = 0, aggOut = 0;

        c.data.siteList.forEach(function(site) {
            activeSdTotal += (parseFloat(site.activeSd) || 0);
            aggLimit += (parseFloat(site.limit) || 0);
            aggOut += (parseFloat(site.liveOutst) || 0);

            var histArr = c.data.siteMonthly[site.sysId] || [];
            var hist = histArr.find(function(h) { return h.monthKey === c.selectedMonth; });
            if (!hist) {
                hist = { outstanding: 0, salesVolume: 0, salesValue: 0, b0_30: 0, b31_60: 0, b61_90: 0, b91_p: 0 };
            }

            var overdue_lt_60 = hist.b0_30 + hist.b31_60;
            var overdue_60_90 = hist.b61_90;
            var overdue_gt_90 = hist.b91_p;

            var risk = 'No Overdue';
            var riskClass = 'clm-risk-None';
            if (overdue_gt_90 > 0) { risk = 'High'; riskClass = 'clm-risk-High'; }
            else if (overdue_60_90 > 0) { risk = 'Medium'; riskClass = 'clm-risk-Medium'; }
            else if (overdue_lt_60 > 0) { risk = 'Low'; riskClass = 'clm-risk-Low'; }

            c.data.table1Data.push({
                sysId: site.sysId, code: site.code, segment: site.segment, zone: site.zone, region: site.region,
                depot: site.depot, limit: site.limit, activeSd: site.activeSd, sdMultiplier: site.sdMultiplier,
                osSalesRatio: site.osSalesRatio, revenueAtRisk: site.revenueAtRisk, p2Composite: site.p2Composite,
                risk: risk, riskClass: riskClass,
                outstanding: isLatestMonth ? site.liveOutst : hist.outstanding,
                b0_30: hist.b0_30, b31_60: hist.b31_60, b61_90: hist.b61_90, b91_p: hist.b91_p,
                salesVolume: hist.salesVolume, salesValue: hist.salesValue,
                reviewIn: site.reviewIn, reviewColor: site.reviewColor
            });
        });

        var panHistRow = (c.data.monthly || []).find(function(m) { return m.monthKey === c.selectedMonth; });
        if (!panHistRow) panHistRow = { outstanding: 0, b91_p: 0 };

        c.data.liveApiOk = true;
        c.data.liveAggOutst = aggOut;
        c.data.indicators.limit = aggLimit;
        c.data.indicators.outstanding = panHistRow.outstanding;
        c.data.indicators.aggregateOutstanding = aggOut;
        c.data.indicators.available = aggLimit - aggOut;
        c.data.indicators.utilisation = aggLimit > 0 ? Math.round((aggOut / aggLimit) * 100) : 0;
        c.data.indicators.activeSd = activeSdTotal;
        c.data.indicators.od90 = panHistRow.b91_p;
        c.data.indicators.od90Clean = panHistRow.b91_p <= 0;

        c.updateTable();
    };

    c.getSelectedMonthLabel = function() {
        if (!c.data || !c.data.filterMonths) return '';
        var match = c.data.filterMonths.find(function(m) { return m.value === c.selectedMonth; });
        return match ? match.label : '';
    };

    c.openSiteDropdown = function() { c.siteDropdownOpen = true; };

    c.clearSiteSearch = function($event) {
        if ($event) $event.preventDefault();
        c.siteSearch = '';
        c.openSiteDropdown();
    };

    c.getFilteredSites = function() {
        if (!c.data || !c.data.siteList) return [];
        var term = (c.siteSearch || '').toLowerCase();
        if (!term || c.siteSearch.indexOf('·') > -1) return c.data.siteList;
        return c.data.siteList.filter(function(s) {
            return s.code.toLowerCase().indexOf(term) > -1 || s.segment.toLowerCase().indexOf(term) > -1;
        });
    };

    c.selectBottomSite = function(site, $event) {
        if ($event) $event.stopPropagation();
        c.selectedSite = site.sysId;
        c.siteSearch = site.code + ' · ' + site.segment;
        c.updateTable();
        c.siteDropdownOpen = false;
    };

    c.selectSite = function(sysId) {
        var targetSite = c.data.siteList.find(function(s) { return s.sysId === sysId; });
        if (targetSite) {
            c.selectedSite = targetSite.sysId;
            c.siteSearch = targetSite.code + ' · ' + targetSite.segment;
            c.updateTable();
        }
        var el = document.getElementById('c360DetailMD');
        if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    };

    c.updateTable = function() {
        if (!c.data || !c.selectedSite || !c.data.siteMonthly) return;
        c.tableData = c.data.siteMonthly[c.selectedSite] || [];

        var targetSite = c.data.siteList.find(function(s) { return s.sysId === c.selectedSite; });
        if (targetSite && targetSite.limit > 0) {
            c.tableData.forEach(function(row) {
                row.limit = targetSite.limit;
                row.util = Math.round((row.outstanding / row.limit) * 100);
            });
            if (c.tableData.length > 0) {
                c.tableData[c.tableData.length - 1].outstanding = targetSite.liveOutst;
                c.tableData[c.tableData.length - 1].util = Math.round((targetSite.liveOutst / targetSite.limit) * 100);
            }
        }
    };

    // ---- shared chart styling ----
    var MONTH_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

    function shortMonth(r) {
        var key = String(r.monthKey || r.rawMonth || r.month || '');
        var m = key.match(/^(\d{4})-(\d{2})/);
        if (!m) return r.month || '';
        return MONTH_SHORT[parseInt(m[2], 10) - 1] + ' ' + m[1].slice(-2);
    }

    function axisUnit(max) {
        var a = Math.abs(max || 0);
        if (a >= 10000000) return { div: 10000000, sfx: ' Cr' };
        if (a >= 100000)   return { div: 100000,   sfx: ' L' };
        if (a >= 1000)     return { div: 1000,     sfx: ' K' };
        return { div: 1, sfx: '' };
    }
    function trimNum(n) {
        var d = Math.abs(n) >= 100 ? 0 : (Math.abs(n) >= 10 ? 1 : 2);
        return String(parseFloat(n.toFixed(d)));
    }
    function autoTicks(prefix) {
        return {
            maxTicksLimit: 6,
            callback: function(v) {
                if (v === 0) return prefix + '0';
                var u = axisUnit(Math.max(Math.abs(this.max), Math.abs(this.min)));
                return prefix + trimNum(v / u.div) + u.sfx;
            }
        };
    }
    function tipValue(prefix, v) {
        var u = axisUnit(v);
        return prefix + trimNum(v / u.div) + u.sfx;
    }

    function applyChartDefaults() {
        Chart.defaults.font.family = CHART_FONT;
        Chart.defaults.font.size = 12;
        Chart.defaults.color = '#5a6a7a';
    }
    var LEGEND = {
        display: true, position: 'bottom',
        labels: {
            usePointStyle: true, boxWidth: 12, boxHeight: 12, padding: 18, color: '#1a1a1a', font: { weight: '700' },
            sort: function(a, b) { return a.datasetIndex - b.datasetIndex; },
            generateLabels: function(chart) {
                var items = Chart.defaults.plugins.legend.labels.generateLabels(chart);
                items.forEach(function(it) {
                    var ds = chart.data.datasets[it.datasetIndex];
                    if (ds && ds.type === 'line') { it.pointStyle = 'line'; it.lineWidth = 3; it.strokeStyle = ds.borderColor; }
                });
                return items;
            }
        }
    };
    var X_AXIS = { grid: { display: false }, border: { color: '#dde3ea' },
                   ticks: { color: '#1a1a1a', font: { weight: '700' } } };
    var AXIS_TITLE = function(text) { return { display: true, text: text, color: '#3a4451', font: { size: 12, weight: '700' } }; };

    c.drawSalesChart = function() {
        if (!c.data || !c.data.monthly || !c.data.monthly.length) return;

        ensureChartJs(function() {
            var canvas = document.getElementById('c360SalesChartMD');
            if (!canvas) return;
            applyChartDefaults();

            var existing = Chart.getChart(canvas);
            if (existing) existing.destroy();

            var rows = c.data.monthly.slice(-6);
            var chartLabels = rows.map(shortMonth);
            var volumeData  = rows.map(function(r) { return parseSafeNumber(r.salesVolume); });
            var valueData   = rows.map(function(r) { return parseSafeNumber(r.salesValue); });

            c.charts.sales = new Chart(canvas.getContext('2d'), {
                type: 'bar',
                data: {
                    labels: chartLabels,
                    datasets: [
                        {
                            type: 'bar', label: 'Credit Sales Volume (MT)', data: volumeData,
                            yAxisID: 'ySalesVolume', order: 1, pointStyle: 'rect',
                            backgroundColor: '#0b5394', hoverBackgroundColor: '#073b6b',
                            borderRadius: 3, maxBarThickness: 56, categoryPercentage: 0.6
                        },
                        {
                            type: 'line', label: 'Credit Sales Value (₹)', data: valueData,
                            yAxisID: 'ySalesValue', order: 0, tension: 0.35,
                            borderColor: '#E87722', borderWidth: 2.5, backgroundColor: '#ffffff',
                            pointStyle: 'circle', pointRadius: 5, pointHoverRadius: 6,
                            pointBorderWidth: 2, pointBorderColor: '#E87722', pointBackgroundColor: '#ffffff'
                        }
                    ]
                },
                options: {
                    responsive: true, maintainAspectRatio: false, resizeDelay: 0,
                    interaction: { mode: 'index', intersect: false },
                    plugins: {
                        legend: LEGEND,
                        tooltip: {
                            mode: 'index', intersect: false,
                            callbacks: {
                                label: function(ctx) {
                                    var v = ctx.parsed.y || 0;
                                    return ctx.dataset.yAxisID === 'ySalesValue'
                                        ? ' Value: ' + tipValue('₹', v)
                                        : ' Volume: ' + tipValue('', v) + ' MT';
                                }
                            }
                        }
                    },
                    scales: {
                        x: X_AXIS,
                        ySalesVolume: {
                            type: 'linear', position: 'left', beginAtZero: true, grace: '10%',
                            grid: { color: '#eef1f5' }, border: { display: false },
                            title: AXIS_TITLE('Volume (MT)'), ticks: autoTicks('')
                        },
                        ySalesValue: {
                            type: 'linear', position: 'right', beginAtZero: true, grace: '10%',
                            grid: { drawOnChartArea: false }, border: { display: false },
                            title: AXIS_TITLE('Value (₹)'),
                            ticks: angular.extend(autoTicks('₹'), { color: '#E87722' })
                        }
                    }
                }
            });
        });
    };

    c.drawAgingChart = function() {
        if (!c.data || !c.data.monthly || !c.data.monthly.length) return;

        ensureChartJs(function() {
            var canvas = document.getElementById('c360AgingChartMD');
            if (!canvas) return;
            applyChartDefaults();

            var existing = Chart.getChart(canvas);
            if (existing) existing.destroy();

            var rows = c.data.monthly.slice(-6);
            var chartLabels = rows.map(shortMonth);

            var b0_30_Data  = rows.map(function(r) { return parseSafeNumber(r.b0_30); });
            var b31_60_Data = rows.map(function(r) { return parseSafeNumber(r.b31_60); });
            var b61_90_Data = rows.map(function(r) { return parseSafeNumber(r.b61_90); });
            var b91_p_Data  = rows.map(function(r) { return parseSafeNumber(r.b91_p); });

            var BAR = { borderColor: '#ffffff', borderWidth: { top: 1 }, maxBarThickness: 56, categoryPercentage: 0.6, pointStyle: 'rectRounded' };
            c.charts.aging = new Chart(canvas.getContext('2d'), {
                type: 'bar',
                data: {
                    labels: chartLabels,
                    datasets: [
                        angular.extend({ label: '0-30D',  data: b0_30_Data,  backgroundColor: '#27ae60' }, BAR),
                        angular.extend({ label: '31-60D', data: b31_60_Data, backgroundColor: '#8fd1a0' }, BAR),
                        angular.extend({ label: '61-90D', data: b61_90_Data, backgroundColor: '#f0a030' }, BAR),
                        angular.extend({ label: '>90D',   data: b91_p_Data,  backgroundColor: '#e23d28' }, BAR)
                    ]
                },
                options: {
                    responsive: true, maintainAspectRatio: false, resizeDelay: 0,
                    interaction: { mode: 'index', intersect: false },
                    plugins: {
                        legend: LEGEND,
                        tooltip: {
                            mode: 'index', intersect: false,
                            callbacks: { label: function(ctx) { return ' ' + ctx.dataset.label + ': ' + tipValue('₹', ctx.parsed.y || 0); } }
                        }
                    },
                    scales: {
                        x: angular.extend({ stacked: true }, X_AXIS),
                        y: {
                            stacked: true, beginAtZero: true, grace: '10%',
                            grid: { color: '#eef1f5' }, border: { display: false },
                            title: AXIS_TITLE('Outstanding (₹)'), ticks: autoTicks('₹')
                        }
                    }
                }
            });
        });
    };

    // =================================================================
    // HAND-OFF FROM PORTFOLIO OVERVIEW
    // =================================================================
    var offCustomerSelected = $rootScope.$on('clm.customer.selected', function(event, payload) {
        var bizFromPayload = (payload && typeof payload === 'object' && payload.business) ? payload.business : (activeBusiness || DEFAULT_BUSINESS);
        if (!applyBusiness(bizFromPayload)) return;
        c.data = {}; c.loading = true; c.selectedMonth = '';
        if (payload && typeof payload === 'object' && payload.sysId) {
            c.load({ sysId: payload.sysId, code: payload.code, pan: payload.pan });
        } else {
            c.load(payload);
        }
    });
    $scope.$on('$destroy', function() { offCustomerSelected(); });

    if ($rootScope.clmPendingCustomerSysId) {
        var pendingSysId = $rootScope.clmPendingCustomerSysId;
        var pendingCode  = $rootScope.clmPendingCustomerCode;
        var pendingPan   = $rootScope.clmPendingCustomerPan;
        var pendingBiz   = $rootScope.clmPendingCustomerBusiness || DEFAULT_BUSINESS;
        delete $rootScope.clmPendingCustomerSysId;
        delete $rootScope.clmPendingCustomerCode;
        delete $rootScope.clmPendingCustomerPan;
        delete $rootScope.clmPendingCustomerBusiness;
        if (applyBusiness(pendingBiz)) {
            c.load({ sysId: pendingSysId, code: pendingCode, pan: pendingPan });
        } else {
            c.loading = false;
        }
    } else {
			delete $rootScope.clmC360PreselectBusiness;
        c.load();   // no customer yet (or a ?search= deep link, which the server scopes to Trade)
    }
}

sp_widget.css:
/* =========================================================================
   CLM Customer 360 (MD1) — CSS  v2.3
   - Business filter in the search block (.clm-c3-biz / .clm-c3-biz-select): highlighted in yellow
     until a business is chosen; disabled options greyed
   - Disabled state for the Customer Search input, label and button
   - Business chip in the context bar (.clm-c3-chip-biz)
   - Empty-state hint card with icon + title; loading state
   v2.2
   - Tables: 2px vertical section dividers removed — only the tinted group header row and row lines
   v2.1
   - Sticky context bar (.clm-c3-context) with Reporting Month picker
   - Merged "Ageing" group header (.bg-ageing), bucket tints on the sub-headers
   v2.0
   - Rewritten on the CLM design system with a widget prefix (clm-c3-)
   - Oxygen font rule kept LAST
   ========================================================================= */
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

.clm-c360 { color:#1a1a1a; background:#f4f5f7; padding:20px; }

/* ---------- Section ---------- */
.clm-c3-section { margin-top:16px; background:#fff; border:1px solid #e0e6ed; border-radius:8px; padding:24px 28px; }
.clm-c3-section-title { display:flex; align-items:center; gap:12px; margin-bottom:18px;
  font-size:14px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:1px; }
.clm-c3-section-num { width:26px; height:26px; border-radius:50%; background:#F3D54E; color:#1a1a1a;
  font-size:13px; font-weight:700; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0; }

/* ---------- Card (block) ---------- */
.clm-c3-block { margin-top:16px; background:#fff; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-c3-first { margin-top:0; }
.clm-c3-head { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:14px 20px; background:#fafbfc; border-bottom:1px solid #dde3ea; }
.clm-c3-title { display:flex; align-items:center; gap:10px; font-size:13px; font-weight:700; color:#1a1a1a;
  text-transform:uppercase; letter-spacing:.8px; }
.clm-c3-title::before { content:""; width:4px; height:16px; border-radius:2px; background:#F3D54E; flex-shrink:0; }
.clm-c3-sub { margin:4px 0 0 14px; font-size:12px; color:#5a6a7a; }
.clm-c3-meta { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-c3-body { padding:18px 20px; }

.clm-c3-block-dev { border-color:#f3c2bc; }
.clm-c3-block-dev .clm-c3-head { background:#fef5f4; border-bottom:0; }
.clm-c3-block-dev .clm-c3-title { color:#b3261e; text-transform:none; letter-spacing:0; }
.clm-c3-block-dev .clm-c3-title::before { background:#E23D28; }

.clm-c3-hint { padding:24px; text-align:center; font-size:13px; color:#5a6a7a; }

/* ---------- Chips ---------- */
.clm-c3-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 10px; background:#fff;
  border:1px solid #dde3ea; border-radius:12px; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-c3-chip-k { font-weight:400; color:#5a6a7a; }
.clm-c3-chip-live { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-c3-chip-req  { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }

.clm-c3-month { margin:0; padding:2px 4px 2px 10px; cursor:pointer; }
.clm-c3-month select { height:26px; padding:0 6px; border:0; background:transparent; outline:none; cursor:pointer;
  font-size:12px; font-weight:700; color:#1a1a1a; }

.clm-c3-spin { width:12px; height:12px; border:2px solid #cfead8; border-top-color:#1e8449; border-radius:50%;
  animation:clm-c3-spin 1s linear infinite; }
.clm-c3-chip-req .clm-c3-spin { border-color:#f6e7a6; border-top-color:#7a5a00; }
@keyframes clm-c3-spin { to { transform:rotate(360deg); } }

/* ---------- Search ---------- */
.clm-c3-search { margin-top:0; overflow:visible; }
.clm-c3-search-row { display:flex; align-items:center; gap:12px; flex-wrap:wrap; padding:14px 20px; }
.clm-c3-search-k { display:flex; align-items:center; gap:10px; font-size:13px; font-weight:700; color:#1a1a1a;
  text-transform:uppercase; letter-spacing:.8px; }
.clm-c3-search-k::before { content:""; width:4px; height:16px; border-radius:2px; background:#F3D54E; }
.clm-c3-search-hint { font-size:12px; color:#7f8c9a; }
.clm-c3-search-live { margin-left:auto; }

.clm-c3-input { width:100%; height:36px; padding:6px 12px; box-sizing:border-box; border:1px solid #cdd4dc;
  border-radius:6px; font-size:13px; color:#1a1a1a; background:#fff; outline:none;
  transition:border-color .15s ease, box-shadow .15s ease; }
.clm-c3-input:focus { border-color:#1a1a1a; box-shadow:0 0 0 3px rgba(243,213,78,.45); }

.clm-c3-btn { height:36px; padding:0 18px; border:1px solid #1a1a1a; border-radius:6px; background:#1a1a1a;
  color:#F3D54E; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; cursor:pointer; white-space:nowrap; }
.clm-c3-btn:hover { background:#333; }

.clm-c3-typeahead { position:relative; flex:0 1 320px; min-width:220px; }
.clm-c3-suggest { position:absolute; top:calc(100% + 4px); left:0; right:0; z-index:9999; max-height:280px; overflow-y:auto;
  margin:0; padding:4px 0; list-style:none; background:#fff; border:1px solid #dde3ea; border-top:2px solid #F3D54E;
  border-radius:6px; box-shadow:0 6px 18px rgba(0,0,0,.10); }
.clm-c3-suggest li { display:flex; justify-content:space-between; align-items:center; gap:12px; padding:8px 12px;
  border-bottom:1px solid #eef1f5; font-size:13px; cursor:pointer; }
.clm-c3-suggest li:last-child { border-bottom:0; }
.clm-c3-suggest li:hover { background:#fffcf0; }
.clm-c3-sug-name { flex:1; font-weight:700; color:#1a1a1a; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.clm-c3-sug-meta { flex-shrink:0; padding:2px 6px; border-radius:4px; background:#eef1f5; font-size:11px; color:#5a6a7a; white-space:nowrap; }
.clm-c3-suggest-loading { pointer-events:none; }
.clm-c3-suggest-msg { padding:10px 12px; font-size:12px; font-style:italic; color:#7f8c9a; }

/* ---------- KPI cards: factor tiles + result row ---------- */
.clm-c3-kpi-row { display:grid; grid-template-columns:minmax(0,2fr) minmax(0,1fr); gap:16px; margin-top:16px; }
.clm-c3-kpi-row > .clm-c3-block { margin-top:0; }
.clm-c3-kpi-row.clm-c3-first { margin-top:0; }
.clm-c3-kpi-card { display:flex; flex-direction:column; }
.clm-c3-kpi-card .clm-c3-body { flex:1; }

.clm-c3-factors { display:grid; gap:12px; }
.clm-c3-factors-4 { grid-template-columns:repeat(4,minmax(0,1fr)); }
.clm-c3-factors-2 { grid-template-columns:repeat(2,minmax(0,1fr)); }
.clm-c3-factor { padding:12px 14px; border:1px solid #e0e6ed; border-radius:6px; background:#fafbfc; }
.clm-c3-factor-k { margin-bottom:4px; font-size:12px; color:#5a6a7a; }
.clm-c3-factor-v { font-size:18px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-c3-factor-s { margin-top:4px; font-size:11px; color:#7f8c9a; }
.clm-c3-factor.is-ok  { background:#f4fbf6; border-color:#cfead8; } .clm-c3-factor.is-ok  .clm-c3-factor-v { color:#1e8449; }
.clm-c3-factor.is-bad { background:#fef5f4; border-color:#f5c2bc; } .clm-c3-factor.is-bad .clm-c3-factor-v { color:#c0392b; }

.clm-c3-res { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:16px 20px; background:#fffcf0; border-top:1px solid #f1e2a0; }
.clm-c3-res-k { font-size:13px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-c3-res-f { margin-top:3px; font-size:12px; color:#7f8c9a; }
.clm-c3-res-v { margin-left:auto; font-size:30px; font-weight:700; line-height:1.1; color:#1a1a1a; }
.clm-c3-res.is-ok  { background:#f4fbf6; border-top-color:#b9e3c6; } .clm-c3-res.is-ok  .clm-c3-res-v { color:#1e8449; }
.clm-c3-res.is-bad { background:#fef5f4; border-top-color:#f5c2bc; } .clm-c3-res.is-bad .clm-c3-res-v { color:#c0392b; }

/* ---------- Charts ---------- */
.clm-c3-chart-row { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
.clm-c3-chart-wrap { position:relative; height:280px; padding:14px 16px 12px; box-sizing:border-box; }
.clm-c3-chart-wrap canvas { width:100% !important; height:100% !important; }

/* ---------- Tables ---------- */
.clm-c3-table-wrap { overflow-x:auto; background:#fff; }
.clm-c3-table-scroll { max-height:460px; overflow-y:auto; }
.clm-c3-table { width:100%; border-collapse:separate; border-spacing:0; font-size:13px; font-variant-numeric:tabular-nums; }
.clm-c3-table th { background:#eef1f5; color:#2b3440; padding:10px 12px; font-size:12px; font-weight:700;
  text-transform:uppercase; letter-spacing:.6px; text-align:center; white-space:nowrap;
  border-bottom:1px solid #dde3ea; }
.clm-c3-table td { padding:12px; color:#1a1a1a; text-align:center; white-space:nowrap; vertical-align:middle;
  border-bottom:1px solid #e6eaef; background:#fff; }
.clm-c3-table tr > :first-child { text-align:left; }
.clm-c3-table tbody tr:last-child td { border-bottom:0; }
.clm-c3-table .grp { border-left:0; }
.clm-c3-table-wide th { font-size:11px; padding:9px 10px; }
.clm-c3-table-wide td { padding:10px; }

/* group row */
.clm-c3-table tr.super th { height:36px; box-sizing:border-box; padding:0 12px; letter-spacing:1px; }
.clm-c3-table th.bg-blank  { background:#f7f8fa; }
.clm-c3-table th.bg-code   { background:#e3eefa; color:#0b5394; }
.clm-c3-table th.bg-pan    { background:#fdf3e1; color:#a35400; }
.clm-c3-table th.bg-seg    { background:#f1f3f7; color:#3a4451; }
.clm-c3-table th.bg-req    { background:#e6f4ea; color:#2e7d32; }
.clm-c3-table th.bg-assess { background:#efe9f9; color:#6a3fb5; }
.clm-c3-table th.bg-ageing { background:#e3f2e7; color:#14532d; }
/* ageing bucket colours */
.clm-c3-table th.ag-safe { background:#d9eedd; color:#14532d; }  .clm-c3-table th.ag-safe-sub { background:#edf7ef; color:#14532d; }
.clm-c3-table th.ag-warn { background:#fde4c4; color:#7a4100; }  .clm-c3-table th.ag-warn-sub { background:#fff4e5; color:#7a4100; }
.clm-c3-table th.ag-risk { background:#f8d7d3; color:#8f1d16; }  .clm-c3-table th.ag-risk-sub { background:#fdeeec; color:#8f1d16; }

/* sticky two-row header + sticky first column (site table) */
.clm-c3-table-scroll thead th { position:sticky; z-index:3; }
.clm-c3-table-scroll thead tr.super th { top:0; }
.clm-c3-table-scroll thead tr.cols th  { top:36px; }
.clm-c3-table-scroll tr > :first-child { position:sticky; left:0; z-index:2; }
.clm-c3-table-scroll thead tr > :first-child { z-index:4; }

/* cells */
.clm-c3-site-code { font-weight:700; color:#1a1a1a; }
.clm-c3-cell-sub { margin-top:2px; font-size:12px; color:#5a6a7a; }
.clm-c3-empty { padding:24px !important; text-align:center !important; color:#7f8c9a; }
.clm-c3-table td.v-key { font-weight:700; }
.clm-c3-table td.v-bad  { color:#c0392b; font-weight:700; }
.clm-c3-table td.v-warn { color:#a15a00; font-weight:700; }
.clm-c3-table td.zero { color:#b0b9c4; }
.clm-c3-table td.warn-val { color:#a15a00; font-weight:700; background:#fffaf2; }
.clm-c3-table td.risk-val { color:#b3261e; font-weight:700; background:#fff6f5; }

/* clickable / selected rows */
.clm-c3-click { cursor:pointer; }
.clm-c3-click:hover td { background:#fafbfc; }
.clm-c3-table tr.is-selected td { background:#fffcf0; }
.clm-c3-table tr.is-selected > :first-child { box-shadow:inset 4px 0 0 #F3D54E; }

/* risk rating chip */
.clm-c3-rating { display:inline-block; padding:3px 10px; border-radius:12px; border:1px solid; font-size:11.5px; font-weight:700; }
.clm-c3-rating.r-a { background:#eaf7ee; color:#1e8449; border-color:#b9e3c6; }
.clm-c3-rating.r-b { background:#fff4e0; color:#a15a00; border-color:#f6d39a; }
.clm-c3-rating.r-c { background:#fdecea; color:#b3261e; border-color:#f5c2bc; }
.clm-c3-rating.r-n { background:#f5f7f9; color:#5a6a7a; border-color:#dde3ea; }

/* classes returned by the scripts (review-in, revenue at risk) */
.clm-text-red    { color:#c0392b !important; }
.clm-text-orange { color:#a15a00 !important; }
.clm-text-green  { color:#1e8449 !important; }
.clm-text-muted  { color:#7f8c9a !important; font-weight:400; }
.clm-risk-negative { color:#c0392b !important; }
.clm-risk-positive { color:#1e8449 !important; }
.clm-risk-neutral  { color:#7f8c9a !important; font-weight:400; }

/* ---------- Site dropdown (detail card head) ---------- */
.clm-c3-dd { position:relative; width:280px; }
.clm-c3-dd-input { height:34px; padding-right:48px; }
.clm-c3-dd-clear { position:absolute; right:28px; top:11px; z-index:10; font-size:12px; color:#7f8c9a; cursor:pointer; }
.clm-c3-dd-arrow { position:absolute; right:10px; top:11px; font-size:12px; color:#5a6a7a; pointer-events:none; }
.clm-c3-dd-list { position:absolute; top:calc(100% + 4px); right:0; width:100%; z-index:1000; max-height:220px; overflow-y:auto;
  margin:0 !important; padding:0 !important; list-style:none !important; background:#fff; border:1px solid #dde3ea;
  border-radius:6px; box-shadow:0 6px 12px rgba(0,0,0,.10); text-align:left; }
.clm-c3-dd-list li { display:flex; align-items:center; justify-content:space-between; gap:8px; padding:8px 12px;
  border-bottom:1px solid #eef1f5; font-size:13px; color:#1a1a1a; cursor:pointer; }
.clm-c3-dd-list li:last-child { border-bottom:0; }
.clm-c3-dd-list li:hover { background:#fafbfc; }
.clm-c3-dd-list li.is-active { background:#fffcf0; box-shadow:inset 3px 0 0 #F3D54E; }
.clm-c3-dd-seg { font-size:11px; color:#5a6a7a; }
.clm-c3-dd-none { justify-content:center !important; font-size:12px !important; color:#7f8c9a !important; cursor:default !important; }
#c360DetailMD { overflow:visible; }
#c360DetailMD > .clm-c3-head { border-radius:8px 8px 0 0; }

/* ---------- Context bar: PAN identity + Reporting Month ---------- */
.clm-c3-context { position:sticky; top:0; z-index:20; display:flex; align-items:center; justify-content:space-between;
  gap:12px 24px; flex-wrap:wrap; margin-top:16px; padding:14px 20px; background:#fff;
  border:1px solid #dde3ea; border-left:5px solid #F3D54E; border-radius:8px; box-shadow:0 2px 6px rgba(0,0,0,.05); }
.clm-c3-context-k { font-size:12px; font-weight:700; color:#5a6a7a; text-transform:uppercase; letter-spacing:.6px; }
.clm-c3-context-v { display:flex; align-items:baseline; gap:12px; flex-wrap:wrap; margin-top:2px; }
.clm-c3-context-pan { font-size:20px; font-weight:700; color:#1a1a1a; letter-spacing:.5px; }
.clm-c3-context-name { font-size:14px; font-weight:700; color:#3a4451; }
.clm-c3-context-sub { margin-top:2px; font-size:12px; color:#5a6a7a; }

.clm-c3-month-picker {
    display:grid;
    grid-template-columns:auto auto;
    align-items:center;
    gap:2px 12px;
    margin:0;
    padding: 0 !important;
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    cursor:pointer;
}
.clm-c3-month-picker select:focus {
    outline: none !important;
    border-color: transparent !important;
}

.clm-c3-month-k { font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-c3-month-picker select { grid-row:span 2; height:38px; min-width:130px; padding:0 10px; border:1px solid #1a1a1a;
  border-radius:6px; background:#1a1a1a; color:#F3D54E; font-size:15px; font-weight:700; outline:none; cursor:pointer; }
.clm-c3-month-picker select option { background:#fff; color:#1a1a1a; }
.clm-c3-month-picker select:focus { box-shadow:0 0 0 3px rgba(243,213,78,.5); }
.clm-c3-month-s { font-size:11px; color:#7f8c9a; }

/* ---------- Business filter + search gating (v2.3) ---------- */
.clm-c3-biz { display:flex; align-items:center; gap:12px; margin:0; font-weight:normal; }
.clm-c3-biz-select { height:36px; min-width:180px; padding:0 10px; box-sizing:border-box; border:1px solid #cdd4dc; border-radius:6px;
  background:#fff; font-size:13px; font-weight:700; color:#1a1a1a; outline:none; cursor:pointer;
  transition:border-color .15s ease, box-shadow .15s ease; }
.clm-c3-biz-select:hover, .clm-c3-biz-select:focus { border-color:#1a1a1a; }
.clm-c3-biz-select.is-empty { border-color:#e6c43a; background:#fffcf0; color:#5a6a7a; font-weight:400;
  box-shadow:0 0 0 3px rgba(243,213,78,.35); }
.clm-c3-biz-select option { color:#1a1a1a; font-weight:400; }
.clm-c3-biz-select option:disabled { color:#b0b9c4; }
.clm-c3-search-sep { width:1px; height:24px; background:#dde3ea; margin:0 4px; }
.clm-c3-search-k.is-off { color:#9aa5b1; }
.clm-c3-search-k.is-off::before { background:#dde3ea; }
.clm-c3-input:disabled { background:#f6f7f9; border-color:#e6eaef; color:#9aa5b1; cursor:not-allowed; }
.clm-c3-btn:disabled, .clm-c3-btn:disabled:hover { background:#cdd4dc; border-color:#cdd4dc; color:#fff; cursor:not-allowed; }
.clm-c3-chip-biz { margin-left:8px; padding:2px 9px; background:#1a1a1a; border-color:#1a1a1a; color:#F3D54E;
  font-size:11px; letter-spacing:.4px; vertical-align:middle; }

/* empty / loading states */
.clm-c3-hint { display:flex; flex-direction:column; align-items:center; gap:6px; padding:40px 24px; }
.clm-c3-hint > .fa { font-size:28px; color:#cdd4dc; margin-bottom:4px; }
.clm-c3-hint-title { font-size:15px; font-weight:700; color:#1a1a1a; }
.clm-c3-spin-lg { width:22px; height:22px; border-width:3px; margin-bottom:4px; }

/* ---------- Responsive ---------- */
@media (max-width:1100px) {
  .clm-c3-kpi-row { grid-template-columns:1fr; }
  .clm-c3-factors-4 { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@media (max-width:900px) {
  .clm-c3-chart-row { grid-template-columns:1fr; }
  .clm-c3-search-sep { display:none; }
}
@media (max-width:640px) {
  .clm-c360 { padding:12px; }
  .clm-c3-section { padding:16px; }
  .clm-c3-head, .clm-c3-body, .clm-c3-res, .clm-c3-search-row { padding-left:14px; padding-right:14px; }
  .clm-c3-biz { flex:1 1 100%; flex-wrap:wrap; }
  .clm-c3-biz-select { flex:1 1 100%; }
  .clm-c3-typeahead { flex:1 1 100%; }
  .clm-c3-btn { flex:1 1 100%; }
  .clm-c3-search-live { margin-left:0; }
  .clm-c3-factors-4, .clm-c3-factors-2 { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-c3-factor-v { font-size:16px; }
  .clm-c3-res-v { font-size:24px; }
  .clm-c3-meta, .clm-c3-dd { width:100%; }
  .clm-c3-context { position:static; padding:12px 14px; }
  .clm-c3-month-picker { width:100%; grid-template-columns:1fr auto; box-sizing:border-box; }
  .clm-c3-context-pan { font-size:18px; }
  .clm-c3-chart-wrap { height:230px; }
}

/* ---------- One font family (keep LAST) ---------- */
.clm-c360, .clm-c360 *, .clm-c360 input, .clm-c360 select,
.clm-c360 textarea, .clm-c360 button, .clm-c360 table {
  font-family: "Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-c360 .fa { font-family: FontAwesome !important; }

sp_widget.script:
/*
  CLM Customer 360 (MD1) — Server Script  v2.3
  - BUSINESS_CONFIG registry (same keys as Portfolio Overview):
      Trade        -> CG1 = T00 (enabled,  layout 'trade')
      Non-Trade    -> CG1 = N01 (disabled, layout 'nonTrade')
      Key Customer -> CG1 = N00 (disabled, layout 'key')
    Each entry also defines its customer-search fields:
      Trade / Non-Trade : customer name, PAN, customer code
      Key Customer      : customer name, group code, grandparent code, PAN
  - data.businessOptions is always returned so the client can build the Business dropdown
  - Every request (suggest / load / fetch_live_sap) must carry input.business; an unknown or
    disabled business is refused. Deep links (?search=) default to ?business= or Trade
  - suggest + customer lookup use the selected business's search fields and CG1 only
  - PAN site list is scoped to the selected business's CG1 (a Trade view never mixes in N01/N00 sites)
  - Opening a customer by sys_id from another business returns a clear error instead of data
  - Existing Trade view logic moved unchanged into tradeView() and registered in LAYOUT_HANDLERS
  - Fixes: PAN segments / zones were never collected (context bar showed an empty segment list);
    duplicate "var seenSiteCodes" removed
*/
(function() {
    var TABLES = {
        master:    'x_birl3_clm_clm_customer_master1',
        request:   'x_birl3_clm_clm_new_credit_request',
        aging:     'x_birl3_clm_clm_aging_snapshot',
        roleMap:   'x_birl3_clm_role_user_mapping',
        salesVol:  'x_birl3_clm_clm_sales_data',
        salesVal:  'x_birl3_clm_clm_cement_rmc_bpd_values'
    };

    var FIELDS = {
        custCode:    'customer_code_sap',
        custName:    'customer_name',
        custPan:     'pan',
        custCg1:     'cg1',
        custRegion:  'region_name',
        custZone:    'zone',
        custZoneName:'zone_name',
        custSegment: 'segment',
        custSalesOrg:'salesorg',
        custGroupCode:       'group_code',        // Key Customer - confirm field name on the master table
        custGrandparentCode: 'grandparent_code',  // Key Customer - confirm field name on the master table
        systemMultiplier: 'system_multiplier',
        agingCustomer:    'customer',
        snapshotMonth:    'snapshot_month',
        totalOutstanding: 'total_outstanding',
        bucket0_30:       'bucket_0_30_days',
        bucket31_45:      'bucket_31_45_days',
        bucket46_60:      'bucket_46_60_days',
        bucket61_75:      'bucket_61_75_days',
        bucket76_90:      'bucket_76_90_days',
        bucket91_120:     'bucket_91_120_days',
        bucketGt120:      'bucket_gt120_days',
        expectedSob:  'u_tool_expected_sob',
        p2Composite:  'u_tool_p2'
    };

    // =================================================================
    // BUSINESS REGISTRY (single source of truth for the Business filter)
    //   suggestOp : operator used while typing (typeahead)
    //   lookupOp  : operator used on "Search" / Enter
    //   meta      : value shown next to the name in the typeahead list
    // =================================================================
    var TRADE_SEARCH = [
        { field: FIELDS.custName, label: 'Name', suggestOp: 'CONTAINS',   lookupOp: 'CONTAINS', meta: false },
        { field: FIELDS.custCode, label: 'Code', suggestOp: 'STARTSWITH', lookupOp: '=',        meta: true  },
        { field: FIELDS.custPan,  label: 'PAN',  suggestOp: 'STARTSWITH', lookupOp: '=',        meta: true  }
    ];
    var KEY_SEARCH = [
        { field: FIELDS.custName,            label: 'Name',        suggestOp: 'CONTAINS',   lookupOp: 'CONTAINS', meta: false },
        { field: FIELDS.custGroupCode,       label: 'Group',       suggestOp: 'STARTSWITH', lookupOp: '=',        meta: true  },
        { field: FIELDS.custGrandparentCode, label: 'Grandparent', suggestOp: 'STARTSWITH', lookupOp: '=',        meta: true  },
        { field: FIELDS.custPan,             label: 'PAN',         suggestOp: 'STARTSWITH', lookupOp: '=',        meta: true  }
    ];

    var BUSINESS_CONFIG = {
    trade: {
        key: 'trade', label: 'Trade', cg1: 'T00', layout: 'trade', built: true, local: true, order: 1,
        searchPlaceholder: 'Customer name, PAN or customer code',
        searchHint: 'customer name, PAN or customer code',
        searchFields: TRADE_SEARCH
    },
    nonTrade: {
        key: 'nonTrade', label: 'Non-Trade', cg1: 'N01', layout: 'nonTrade', built: true, local: false, order: 2,
        searchPlaceholder: 'Customer name, PAN or customer code',
        searchHint: 'customer name, PAN or customer code',
        searchFields: TRADE_SEARCH
    },
    key: {
        key: 'key', label: 'Key Customer', cg1: 'N00', layout: 'key', built: true, local: false, order: 3,
        searchPlaceholder: 'Customer name, group code, grandparent code or PAN',
        searchHint: 'customer name, group code, grandparent code or PAN',
        searchFields: KEY_SEARCH
    }
};
    var DEFAULT_BUSINESS = 'trade';

// Trade access = role mapping table (u_user + u_role MD / MD1). Same check gates every option here.
function hasRoleAccess() {
    var gr = new GlideRecord(TABLES.roleMap);
    if (!gr.isValid()) return false;
    gr.addQuery('u_user', gs.getUserID());
    gr.addEncodedQuery('u_role=MD^ORu_role=MD1');
    gr.setLimit(1); gr.query();
    return gr.hasNext();
}
var ACCESS = new CLMBusinessAccess().getAccess('MD');

function getBusinessOptions() {
    var arr = [];
    for (var k in BUSINESS_CONFIG) {
        if (!BUSINESS_CONFIG.hasOwnProperty(k)) continue;
        var b = BUSINESS_CONFIG[k];
        if (!ACCESS[b.key]) continue;                       // user has no access: not listed at all
        arr.push({ value: b.key, label: b.label, cg1: b.cg1, layout: b.layout, enabled: !!b.built, order: b.order });
    }
    arr.sort(function(a, b) { return a.order - b.order; });
    return arr;
}
    function resolveBusiness(key) {
        if (!key) return null;
        key = String(key);
        return BUSINESS_CONFIG.hasOwnProperty(key) ? BUSINESS_CONFIG[key] : null;
    }

    // Only search fields that exist on the master table are used (protects against unconfirmed Key fields)
    var _validFieldCache = {};
    function validSearchFields(biz) {
        if (_validFieldCache[biz.key]) return _validFieldCache[biz.key];
        var probe = new GlideRecord(TABLES.master);
        var out = [];
        biz.searchFields.forEach(function(f) {
            if (probe.isValidField(f.field)) out.push(f);
            else gs.warn('CLM C360: search field "' + f.field + '" not found on ' + TABLES.master + ' (' + biz.label + ')');
        });
        _validFieldCache[biz.key] = out;
        return out;
    }
    function addSearchConditions(gr, biz, term, opKey) {
        var fields = validSearchFields(biz);
        if (!fields.length) return false;
        var q = gr.addQuery(fields[0].field, fields[0][opKey], term);
        for (var i = 1; i < fields.length; i++) q.addOrCondition(fields[i].field, fields[i][opKey], term);
        return true;
    }
    function buildMeta(gr, biz) {
        var parts = [];
        validSearchFields(biz).forEach(function(f) {
            if (!f.meta) return;
            var v = gr.getValue(f.field);
            if (v) parts.push(v);
        });
        return parts.join(' \u00b7 ');
    }

    var MONTH_ABBR = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    function pad2(n) { return n < 10 ? '0' + n : '' + n; }
    var currentUserId = gs.getUserID();
    var gdtToday = new GlideDateTime();

    // =================================================================
    // GET LIVE API CREDIT DETAILS (Parses ASDAmount)
    // =================================================================
   /* function getLiveCreditData(customerCode, salesOrg) {
        var out = { creditLimit: 0, outstandingAmount: 0, activeSd: 0, state: '', raw: null, success: false };
        if (!customerCode) return out;
        try {
            var apiCall = new x_birl3_clm.CLM_NEW_WSDL1();
            var rawResult = apiCall.getCreditDetails(customerCode, salesOrg || '');
            if (!rawResult) return out;

            var parsed = JSON.parse(rawResult);
            out.creditLimit       = parseFloat(parsed.creditLimit) || 0;
            out.outstandingAmount = parseFloat(parsed.outstandingAmount) || 0;
            out.activeSd          = Math.abs(parseFloat(parsed.ASDAmount) || 0);
            out.state             = parsed.state || '';
            out.raw = parsed;

            var allBlank = true;
            for (var k in parsed) { if (parsed[k]) { allBlank = false; break; } }
            if (!allBlank) out.success = true;
        } catch (e) { }
        return out;
    }*/

    function numStr(v) {
        if (v === null || v === undefined || v === '') return 0;
        var n = parseFloat(v.toString().replace(/,/g, ''));
        return isNaN(n) ? 0 : n;
    }

    // Always available, even before a business is chosen
    data.businessOptions = getBusinessOptions();
    data.defaultBusiness = DEFAULT_BUSINESS;

    var ALLOWED_ROLES = ['MD', 'MD1'];
    var isAuthorized = false;
    var grRole = new GlideRecord(TABLES.roleMap);
    grRole.addQuery('u_user', currentUserId);
    grRole.addQuery('u_role', 'IN', ALLOWED_ROLES);
    grRole.query();
    if (grRole.next()) { isAuthorized = true; }

    if (!isAuthorized) {
        data.error = 'You do not have access to view this dashboard.';
        return;
    }

    var hasInput = (typeof input !== 'undefined' && input);
    var action = hasInput ? (input.action || '') : '';
    var spParam = function(name) { return (typeof $sp !== 'undefined') ? ($sp.getParameter(name) || '') : ''; };

function requireBusiness(key) {
    var biz = resolveBusiness(key);
    if (!biz) { data.error = 'Select a business before searching for a customer.'; data.businessRequired = true; return null; }
    if (!biz.built) { data.error = 'Customer 360 for ' + biz.label + ' customers is not available yet.'; data.layoutUnavailable = true; return null; }
    if (!biz.local) { data.error = biz.label + ' customers are served by their own Customer 360 widget.'; data.layoutUnavailable = true; return null; }
    return biz;
}

    // ---------- Layout handlers (add nonTrade / key when their views are built) ----------
    //   nonTrade: { view: nonTradeView },
    //   key:      { view: keyView }      // e.g. Grandparent -> Group -> Zone -> Site hierarchy
    var LAYOUT_HANDLERS = {
        trade: { view: tradeView }
    };

    // --- ASYNC SAP FETCH ACTION ---
   /* if (action === 'fetch_live_sap') {
        if (!requireBusiness(input.business)) return;
        data.liveResults = {};
        var sitesToFetch = input.sites || [];
        for (var i = 0; i < sitesToFetch.length; i++) {
            var s = sitesToFetch[i];
            var liveSap = getLiveCreditData(s.code, s.salesOrg);

            data.liveResults[s.sysId] = {
                limit: liveSap.creditLimit,
                liveOutst: liveSap.outstandingAmount,
                available: liveSap.creditLimit - liveSap.outstandingAmount,
                util: liveSap.creditLimit > 0 ? Math.round((liveSap.outstandingAmount / liveSap.creditLimit) * 100) : 0,
                activeSd: liveSap.activeSd,
                state: liveSap.state,
                success: liveSap.success
            };
        }
        return;
    }*/

    // --- TYPEAHEAD (scoped to the selected business) ---
    if (action === 'suggest') {
        data.suggestions = [];
        var sugBiz = requireBusiness(input.business);
        if (!sugBiz) return;
        var term = (input.term || '').trim();
        if (term.length < 2) return;

        var grSug = new GlideRecord(TABLES.master);
        if (!addSearchConditions(grSug, sugBiz, term, 'suggestOp')) return;
        grSug.addQuery(FIELDS.custCg1, sugBiz.cg1);
        grSug.orderBy(FIELDS.custName);
        grSug.setLimit(8);
        grSug.query();

        var seen = {};
        while (grSug.next()) {
            var code = grSug.getValue(FIELDS.custCode);
            if (seen[code]) continue;
            seen[code] = true;
            data.suggestions.push({
                sysId: grSug.getUniqueValue(),
                name: grSug.getValue(FIELDS.custName),
                code: code,
                pan:  grSug.getValue(FIELDS.custPan),
                meta: buildMeta(grSug, sugBiz)
            });
        }
        return;
    }

    // --- MAIN LOAD ---
    data.error = null;
    data.initialLoad = false;
    data.panIdentity = null;
    data.siteList = [];

    var directSysId = (hasInput && input.sysId) ? input.sysId : '';
    var rawSearch = (hasInput && input.search) ? input.search :
                    (typeof options !== 'undefined' && options.search ? options.search : spParam('search'));
    var searchTerm = rawSearch ? String(rawSearch).trim() : '';

    if (!directSysId && !searchTerm) {
        data.initialLoad = true;
        return;
    }

    // Manual search sends input.business; deep links (?search=) fall back to ?business= or Trade
    var bizKey = (hasInput && input.business) ? input.business : (spParam('business') || DEFAULT_BUSINESS);
    var biz = requireBusiness(bizKey);
    if (!biz) return;
    data.business = biz.key;
    data.layout = biz.layout;

    var grCustLookup = new GlideRecord(TABLES.master);
    if (directSysId) {
        grCustLookup.addQuery('sys_id', directSysId);
    } else {
        if (!addSearchConditions(grCustLookup, biz, searchTerm, 'lookupOp')) { data.error = 'No search fields configured for ' + biz.label + '.'; return; }
    }
    grCustLookup.addQuery(FIELDS.custCg1, biz.cg1);
    grCustLookup.setLimit(1);
    grCustLookup.query();

    if (!grCustLookup.next()) {
        data.error = directSysId
            ? 'This customer is not a ' + biz.label + ' customer (CG1 ' + biz.cg1 + ').'
            : 'No ' + biz.label + ' customer found for "' + searchTerm + '".';
        return;
    }

    var handler = LAYOUT_HANDLERS[biz.layout];
    if (!handler || !handler.view) { data.error = 'Customer 360 for ' + biz.label + ' customers is not available yet.'; data.layoutUnavailable = true; return; }
    handler.view(grCustLookup, biz);

    // =================================================================
    // TRADE VIEW (PAN -> site codes), scoped to CG1 = biz.cg1
    // =================================================================
    function tradeView(grCust, biz) {
        data.filterMonths = [];
        var nDate = new Date();
        for (var fm = 1; fm <= 6; fm++) {
            var d = new Date(nDate.getFullYear(), nDate.getMonth() - fm, 1);
            var ym = d.getFullYear() + '-' + pad2(d.getMonth() + 1);
            var lbl = MONTH_ABBR[d.getMonth()].charAt(0).toUpperCase() + MONTH_ABBR[d.getMonth()].slice(1) + ' ' + String(d.getFullYear()).slice(-2);
            data.filterMonths.push({ value: ym, label: lbl });
        }
        var selectedMonthVal = data.filterMonths[0].value;
        data.selectedMonthVal = selectedMonthVal;

        var targetPan = grCust.getValue(FIELDS.custPan);
        var panKnown = !!targetPan;
        if (!targetPan) { targetPan = 'UNKNOWN-' + grCust.getValue(FIELDS.custCode); }

        data.panIdentity = { pan: targetPan, primaryName: grCust.getValue(FIELDS.custName), zones: [], segments: [] };

        // Fetch PAN sites of this business only
        var panSysIds = [];
        var siteDataMap = {};
        var zoneSet = {}, segmentSet = {};

        var grPan = new GlideRecord(TABLES.master);
        if (panKnown) grPan.addQuery(FIELDS.custPan, targetPan);
        else grPan.addQuery('sys_id', grCust.getUniqueValue());
        grPan.addQuery(FIELDS.custCg1, biz.cg1);
        grPan.query();

        var seenSiteCodes = {};
        var panCustCodes = []; // SAP codes used to map the requests

        while (grPan.next()) {
            var sId = grPan.getUniqueValue();
            var sCode = (grPan.getValue(FIELDS.custCode) || '') + '';

            if (seenSiteCodes[sCode]) continue;
            seenSiteCodes[sCode] = true;

            var sZone = grPan.getDisplayValue(FIELDS.custZoneName) || grPan.getDisplayValue(FIELDS.custZone);
            var sSeg = grPan.getDisplayValue(FIELDS.custSegment);
            if (sZone) zoneSet[sZone] = true;
            if (sSeg) segmentSet[sSeg] = true;

            panSysIds.push(sId);
            if (sCode && sCode !== 'null') panCustCodes.push(sCode);

            siteDataMap[sId] = {
                sysId: sId, code: sCode, salesOrg: grPan.getValue(FIELDS.custSalesOrg),
                name: grPan.getValue(FIELDS.custName), segment: sSeg, zone: sZone,
                region: grPan.getDisplayValue(FIELDS.custRegion),
                depot: grPan.getDisplayValue('depot_name') || grPan.getDisplayValue('depot'),
                crLimit: numStr(grPan.getValue('cr_limit')),
                outstanding: numStr(grPan.getValue('ughai_after_adjustment_net_os')),
                activeSd: Math.abs(numStr(grPan.getValue('current_sd_amount')))
            };
        }

        data.panIdentity.zones = Object.keys(zoneSet);
        data.panIdentity.segments = Object.keys(segmentSet);

        // Fetch Request Data
        var siteReqData = {};
        var grReqBulk = new GlideRecord(TABLES.request);
        var qcReq = grReqBulk.addQuery('customer', 'IN', panCustCodes);
        qcReq.addOrCondition('customer', 'IN', panSysIds);
        qcReq.addOrCondition('customer.customer_code_sap', 'IN', panCustCodes);
        grReqBulk.orderByDesc('sys_created_on');
        grReqBulk.query();

        while (grReqBulk.next()) {
            var rawCustomer = (grReqBulk.getValue('customer') || '') + '';
            var refCode = (grReqBulk.customer.customer_code_sap || '') + '';

            var mapKey = '';
            if (rawCustomer && panCustCodes.indexOf(rawCustomer) > -1) {
                mapKey = rawCustomer;
            } else if (refCode && panCustCodes.indexOf(refCode) > -1) {
                mapKey = refCode;
            } else if (siteDataMap[rawCustomer]) {
                mapKey = siteDataMap[rawCustomer].code;
            } else {
                mapKey = rawCustomer;
            }

            if (!siteReqData[mapKey]) {
                var sobRaw = grReqBulk.getValue(FIELDS.expectedSob);
                var sobNum = parseFloat(sobRaw);
                siteReqData[mapKey] = {
                    sdMultiplier: parseFloat(grReqBulk.getValue(FIELDS.systemMultiplier)) || 0,
                    reviewDate: grReqBulk.getValue('next_review_date'),
                    expectedSob: isNaN(sobNum) ? null : sobNum,
                    p2Composite: ''
                };
            }

            // Scan older requests so P2 is found even if the newest request is blank
            if (!siteReqData[mapKey].p2Composite) {
                var rawDirect = grReqBulk.u_tool_p2 + '';
                var rawGet = grReqBulk.getValue('u_tool_p2') || '';
                var finalP2 = (rawDirect !== 'undefined' && rawDirect !== 'null' && rawDirect.trim() !== '') ? rawDirect : rawGet;
                if (finalP2 && finalP2.trim() !== '') {
                    siteReqData[mapKey].p2Composite = finalP2.trim();
                }
            }
        }

        // Fetch Sales Data
        var monthlySalesValueMap = {};
        var monthlySalesVolumeMap = {};
        var siteSalesAvgMap = {};

        var grSalesValBulk = new GlideRecord(TABLES.salesVal);
        grSalesValBulk.addQuery('u_customer', 'IN', panSysIds);
        grSalesValBulk.query();
        while (grSalesValBulk.next()) {
            var custIdVal = grSalesValBulk.getValue('u_customer');
            if (!custIdVal) continue;
            if (!monthlySalesValueMap[custIdVal]) monthlySalesValueMap[custIdVal] = {};

            var sum12 = 0, count12 = 0;
            for (var i = 0; i < 12; i++) {
                var dM = new Date(nDate.getFullYear(), nDate.getMonth() - i, 1);
                var mthAbbr = MONTH_ABBR[dM.getMonth()];
                var ymV = dM.getFullYear() + '-' + pad2(dM.getMonth() + 1);

                var valRaw = grSalesValBulk.getValue(mthAbbr) || grSalesValBulk.getValue('u_' + mthAbbr);
                var v = parseFloat(valRaw);
                if (!isNaN(v)) {
                    monthlySalesValueMap[custIdVal][ymV] = v;
                    sum12 += v; count12++;
                }
            }
            siteSalesAvgMap[custIdVal] = count12 > 0 ? (sum12 / count12) : null;
        }

        var grSalesVolBulk = new GlideRecord(TABLES.salesVol);
        grSalesVolBulk.addQuery('u_customer', 'IN', panSysIds);
        grSalesVolBulk.query();
        while (grSalesVolBulk.next()) {
            var custIdVol = grSalesVolBulk.getValue('u_customer');
            if (!custIdVol) continue;
            if (!monthlySalesVolumeMap[custIdVol]) monthlySalesVolumeMap[custIdVol] = {};

            for (var j = 0; j < 6; j++) {
                var d6 = new Date(nDate.getFullYear(), nDate.getMonth() - j, 1);
                var mthAbbrV = MONTH_ABBR[d6.getMonth()];
                var ymVol = d6.getFullYear() + '-' + pad2(d6.getMonth() + 1);

                var volRaw = grSalesVolBulk.getValue(mthAbbrV) || grSalesVolBulk.getValue('u_' + mthAbbrV);
                var vVol = parseFloat(volRaw);
                if (!isNaN(vVol)) {
                    monthlySalesVolumeMap[custIdVol][ymVol] = vVol;
                }
            }
        }

        var aggReqLimit = 0;
        var aggOutstanding = 0;
        var aggActiveSd = 0;

        // Build Site List
        for (var sl = 0; sl < panSysIds.length; sl++) {
            var sIdObj = panSysIds[sl] + '';
            var sData = siteDataMap[sIdObj];
            if (!sData) continue;

            aggReqLimit += sData.crLimit;
            aggOutstanding += sData.outstanding;
            aggActiveSd += sData.activeSd;

            // Request data is keyed by customer_code_sap
            var rData = siteReqData[sData.code] || siteReqData[sIdObj] || {};

            var avgSales = siteSalesAvgMap[sIdObj];
            var siteRevAtRisk = null;
            if (avgSales !== null && avgSales !== undefined && rData.expectedSob !== null && rData.expectedSob !== 0 && rData.expectedSob !== undefined) {
                siteRevAtRisk = ((avgSales - rData.expectedSob) / rData.expectedSob) * 100;
            }

            var reviewDays = '--', reviewColor = 'clm-text-muted';
            if (rData.reviewDate) {
                var diff = GlideDateTime.subtract(gdtToday, new GlideDateTime(rData.reviewDate)).getRoundedDayPart();
                reviewDays = diff + 'd';
                if (diff <= 15) reviewColor = 'clm-text-red';
                else if (diff <= 30) reviewColor = 'clm-text-orange';
                else reviewColor = 'clm-text-green';
            }

            data.siteList.push({
                sysId: sIdObj, code: sData.code, salesOrg: sData.salesOrg,
                name: sData.name, segment: sData.segment, zone: sData.zone,
                region: sData.region, depot: sData.depot,
                limit: sData.crLimit,
                activeSd: sData.activeSd,
                liveOutst: sData.outstanding,
                liveState: '',
                revenueAtRisk: siteRevAtRisk,
                p2Composite: rData.p2Composite || '',
                sdMultiplier: rData.sdMultiplier || 0,
                reviewIn: reviewDays, reviewColor: reviewColor, osSalesRatio: 0
            });
        }

        // HISTORICAL AGING & 6-MONTH CHART AGGREGATION
        var snapMonths = [];
        var grDates = new GlideAggregate(TABLES.aging);
        grDates.addQuery(FIELDS.agingCustomer, 'IN', panSysIds);
        grDates.groupBy(FIELDS.snapshotMonth);
        grDates.orderByDesc(FIELDS.snapshotMonth);
        grDates.setLimit(6);
        grDates.query();
        while (grDates.next()) {
            snapMonths.push(grDates.getValue(FIELDS.snapshotMonth));
        }

        var siteHist = {};
        var panHist = {};

        var grAge = new GlideRecord(TABLES.aging);
        grAge.addQuery(FIELDS.agingCustomer, 'IN', panSysIds);
        grAge.addQuery(FIELDS.snapshotMonth, 'IN', snapMonths);
        grAge.query();

        while (grAge.next()) {
            var aCid = grAge.getValue(FIELDS.agingCustomer);
            var aMonth = grAge.getDisplayValue(FIELDS.snapshotMonth);
            var rawMonth = grAge.getValue(FIELDS.snapshotMonth);
            var yyyy_mm = rawMonth.substring(0, 7);

            var b0   = parseFloat(grAge.getValue(FIELDS.bucket0_30))  || 0;
            var b31  = parseFloat(grAge.getValue(FIELDS.bucket31_45)) || 0;
            var b46  = parseFloat(grAge.getValue(FIELDS.bucket46_60)) || 0;
            var b61  = parseFloat(grAge.getValue(FIELDS.bucket61_75)) || 0;
            var b76  = parseFloat(grAge.getValue(FIELDS.bucket76_90)) || 0;
            var b91  = parseFloat(grAge.getValue(FIELDS.bucket91_120))|| 0;
            var b120 = parseFloat(grAge.getValue(FIELDS.bucketGt120)) || 0;
            var snapOut = parseFloat(grAge.getValue(FIELDS.totalOutstanding)) || 0;

            var mappedVol = (monthlySalesVolumeMap[aCid] && monthlySalesVolumeMap[aCid][yyyy_mm]) ? monthlySalesVolumeMap[aCid][yyyy_mm] : 0;
            var mappedVal = (monthlySalesValueMap[aCid] && monthlySalesValueMap[aCid][yyyy_mm]) ? monthlySalesValueMap[aCid][yyyy_mm] : 0;

            var rowObj = {
                month: aMonth, rawMonth: rawMonth, monthKey: yyyy_mm,
                outstanding: snapOut, salesVolume: mappedVol, salesValue: mappedVal,
                b0_30: b0, b31_60: b31 + b46, b61_90: b61 + b76, b91_p: b91 + b120
            };

            if (!siteHist[aCid]) siteHist[aCid] = {};
            siteHist[aCid][yyyy_mm] = rowObj;

            if (!panHist[yyyy_mm]) {
                panHist[yyyy_mm] = {
                    month: aMonth, rawMonth: rawMonth, monthKey: yyyy_mm, limit: aggReqLimit,
                    outstanding: 0, salesVolume: 0, salesValue: 0,
                    b0_30: 0, b31_60: 0, b61_90: 0, b91_p: 0, util: 0
                };
            }
            panHist[yyyy_mm].outstanding += snapOut;
            panHist[yyyy_mm].salesVolume += mappedVol;
            panHist[yyyy_mm].salesValue += mappedVal;
            panHist[yyyy_mm].b0_30 += b0;
            panHist[yyyy_mm].b31_60 += (b31 + b46);
            panHist[yyyy_mm].b61_90 += (b61 + b76);
            panHist[yyyy_mm].b91_p += (b91 + b120);
        }

        snapMonths.sort();
        data.monthly = [];
        snapMonths.forEach(function(m) {
            var key = m.substring(0, 7);
            if (panHist[key]) {
                panHist[key].util = aggReqLimit > 0 ? Math.round((panHist[key].outstanding / aggReqLimit) * 100) : 0;
                data.monthly.push(panHist[key]);
            }
        });

        data.siteMonthly = {};
        for (var sid in siteHist) {
            data.siteMonthly[sid] = [];
            snapMonths.forEach(function(m) {
                var key = m.substring(0, 7);
                if (siteHist[sid][key]) data.siteMonthly[sid].push(siteHist[sid][key]);
            });
        }

        data.table1Data = [];
        for (var t = 0; t < data.siteList.length; t++) {
            var site = data.siteList[t];

            var custOutSum = 0;
            var custSalSum = 0;
            var hArr = data.siteMonthly[site.sysId] || [];
            for (var h = 0; h < hArr.length; h++) {
                custOutSum += hArr[h].outstanding;
                custSalSum += hArr[h].salesValue;
            }
            site.osSalesRatio = custSalSum > 0 ? (custOutSum / custSalSum) : 0;

            var hist = (siteHist[site.sysId] && siteHist[site.sysId][selectedMonthVal]) ? siteHist[site.sysId][selectedMonthVal] : {
                outstanding: 0, salesVolume: 0, salesValue: 0,
                b0_30: 0, b31_60: 0, b61_90: 0, b91_p: 0
            };

            var isLatestMonth = (selectedMonthVal === data.filterMonths[0].value);
            var overdue_lt_60 = hist.b0_30 + hist.b31_60;
            var overdue_60_90 = hist.b61_90;
            var overdue_gt_90 = hist.b91_p;

            var risk = 'No Overdue';
            var riskClass = 'clm-risk-None';
            if (overdue_gt_90 > 0) { risk = 'High'; riskClass = 'clm-risk-High'; }
            else if (overdue_60_90 > 0) { risk = 'Medium'; riskClass = 'clm-risk-Medium'; }
            else if (overdue_lt_60 > 0) { risk = 'Low'; riskClass = 'clm-risk-Low'; }

            data.table1Data.push({
                sysId: site.sysId, code: site.code, segment: site.segment, zone: site.zone,
                region: site.region, depot: site.depot, limit: site.limit, activeSd: site.activeSd,
                sdMultiplier: site.sdMultiplier, osSalesRatio: site.osSalesRatio, revenueAtRisk: site.revenueAtRisk,
                p2Composite: site.p2Composite, risk: risk, riskClass: riskClass,
                outstanding: isLatestMonth ? site.liveOutst : hist.outstanding,
                b0_30: hist.b0_30, b31_60: hist.b31_60, b61_90: hist.b61_90, b91_p: hist.b91_p,
                salesVolume: hist.salesVolume, salesValue: hist.salesValue,
                reviewIn: site.reviewIn, reviewColor: site.reviewColor
            });
        }

        var selectedPanHist = panHist[selectedMonthVal] || { outstanding: 0, b91_p: 0 };

        // Live values (aggregate OS / available / utilisation) are filled by the async SAP fetch
        data.indicators = {
            limit:                aggReqLimit,
            aggregateOutstanding: aggOutstanding,
            outstanding:          selectedPanHist.outstanding,   // snapshot of selected month
            available:            aggReqLimit - aggOutstanding,
            utilisation:          aggReqLimit > 0 ? Math.round((aggOutstanding / aggReqLimit) * 100) : 0,
            activeSd:             aggActiveSd,
            od90:                 selectedPanHist.b91_p,
            od90Clean:            selectedPanHist.b91_p <= 0
        };
        data.liveApiOk = true;   // kept so any template check on it doesn't show a "live API failed" warning
    }

    // =================================================================
    // NON-TRADE / KEY CUSTOMER views go here when built, e.g.
    //   function nonTradeView(grCust, biz) { ... }
    //   function keyView(grCust, biz)      { ... Grandparent / Group / Zone / Site ... }
    // then register them in LAYOUT_HANDLERS and set enabled: true in BUSINESS_CONFIG.
    // =================================================================
})();
